<script setup lang="ts">
import type {OcrTask} from '../types'
import {ocrStates,ocrStages} from '../utils/ocr-task'
withDefaults(defineProps<{task?:OcrTask;jobId?:string;compact?:boolean}>(),{compact:false})
</script>
<template><view class="ocr-progress" :class="{compact}"><view class="between"><text class="ocr-title">OCR 识别进度</text><text v-if="task" class="tag" :class="{'tag-amber':task.state==='retry_wait'||task.state==='failed'}">{{ocrStates[task.state]||task.state||'后台未返回状态'}}</text></view><view v-if="jobId||task?.jobId" class="task-id"><text>识别任务</text><text selectable>{{task?.jobId||jobId}}</text></view><template v-if="task"><view class="between stage-line"><text>{{ocrStages[task.stage]||task.stage||'后台尚未返回处理阶段'}}</text><text class="percent">{{task.percent===null?'进度未返回':task.percent+'%'}}</text></view><progress v-if="task.percent!==null" :percent="task.percent" :active="false" activeColor="#00965c" backgroundColor="#e8efea" :stroke-width="5"/><text v-if="task.attemptCount!==null" class="attempts">已尝试 {{task.attemptCount}} 次</text><view v-if="task.state==='failed'||task.state==='retry_wait'||task.state==='cancelled'" class="task-error"><text v-if="task.errorCode" class="error-code">{{task.errorCode}}</text><text>{{task.message||'后台尚未提供失败或停止原因'}}</text></view><text v-if="task.state==='queued'" class="task-help">原件已保存，等待识别服务领取任务。</text><text v-else-if="task.state==='retry_wait'" class="task-help">后台将按任务策略重试，无需重复上传。</text><text v-else-if="task.state==='succeeded'" class="task-help">识别结果已保存为候选，仍需医生核对与审核，尚不代表正式归档。</text><text v-else-if="task.state==='failed'||task.state==='cancelled'" class="task-help">原件仍保留。请联系企业管理员核实；本页不发起后台重试或停止操作。</text></template><text v-else class="task-help">后台未返回 OCR 任务信息，请稍后刷新查看。</text></view></template>
